SELECT name
FROM USER
WHERE userNumber = #{userNumber}

SELECT l.lidx, l.lbidx, l.loanDate, l.dueDate, l.returnDate, l.status, l.extended
FROM LOAN l
JOIN USER u ON l.uidx = u.uidx
WHERE l.lidx = #{lidx}
  AND u.userNumber = #{userNumber}
  AND l.delyn = 'N'

mapper.update:
UPDATE LOAN
SET dueDate = #{newDueDate}, extended = 'Y'
WHERE lidx = #{lidx}
